# Convert RGB565 to RGB888
def rgb565_to_rgb888(rgb565):
    red = (rgb565 >> 11) & 0x1F
    green = (rgb565 >> 5) & 0x3F
    blue = rgb565 & 0x1F

    # Scale to 8-bit range
    red = (red << 3) | (red >> 2)
    green = (green << 2) | (green >> 4)
    blue = (blue << 3) | (blue >> 2)

    return red, green, blue

# Create a 3D NumPy array for RGB888
height = len(rgb565_image)
width = len(rgb565_image[0])
rgb888_image = np.zeros((height, width, 3), dtype=np.uint8)

for y in range(height):
    for x in range(width):
        rgb888_image[y, x] = rgb565_to_rgb888(rgb565_image[y][x])

# Display the image
plt.figure(figsize=(6, 6))
plt.imshow(rgb888_image, interpolation="nearest")
plt.grid(True, which="both", color="gray", linestyle="--", linewidth=0.5)
plt.title("RGB888 image", fontproperties=prop)
plt.xlabel("x-axis (pixels)", fontproperties=prop)
plt.ylabel("y-axis (pixels)", fontproperties=prop)
plt.tick_params(axis='both', which='major', labelsize=10)

